//! 🔗️ Immutable first-party aliases share one retained clone lifecycle without copying their payload graph.
use super::*;
/// 🎟️ A defining immutable owner declares its actual alias operation independently of payload cloning.
pub trait RetainedAlias:RetireOwned+Sync{fn alias_demand(&self)->RetirementDemand;fn alias_work_demand(&self)->u64;fn admit_alias_into<'reply>(&self,output:&mut Option<Self>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError> where Self:Sized;fn recover_alias_into<'reply>(&self,output:&mut Option<Self>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError> where Self:Sized;}
struct AliasState<T:RetainedAlias>{output:Option<T>,source:Option<RetainedCloneBinding>,close:RetainedCloneClose,closing:bool,spent:bool,advance_action:Option<crate::OriginalEffectInvocationIdentity>,close_route:Option<(crate::OriginalEffectInvocationIdentity,u8)>}
/// 🧷️ The original source remains issued until the result and every cancelled alias physically close.
pub struct RetainedAliasCursor<T:RetainedAlias>{state:ManuallyDrop<AliasState<T>>}
impl<T:RetainedAlias> Default for RetainedAliasCursor<T>{fn default()->Self{Self{state:ManuallyDrop::new(AliasState{output:None,source:None,close:Default::default(),closing:false,spent:false,advance_action:None,close_route:None})}}}
fn alias_invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original immutable alias changed its source or lifecycle")}
impl<T:RetainedAlias+RetainedClone> RetainedCloneCursor<T> for RetainedAliasCursor<T>{
 fn requires_original_birth(&self)->bool{if !self.state.close.is_empty(){self.state.close.requires_original_birth()}else if self.state.output.is_some(){false}else{RetainedCloneBinding::requires_original_birth(&self.state.source)}}
 fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->crate::OriginalRetirementPoll{if !self.state.close.is_empty(){self.state.close.step_original_birth(original,grant)}else if self.state.output.is_some(){crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::invariant("original Birth is not the selected cursor frontier").into()),work:0})}else{RetainedCloneBinding::close_original_birth_step(&mut self.state.source,original,grant)}}
 fn requires_original_control(&self)->bool{if !self.state.close.is_empty(){self.state.close.requires_original_control()}else if self.state.output.is_some(){false}else{RetainedCloneBinding::requires_original_control(&self.state.source)}}
 fn close_into<'reply>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.state.closing{return Err(ValueError::invariant("cursor must begin close"))}if self.requires_original_birth()||self.requires_original_control(){return Err(ValueError::invariant("cursor requires selected original close"))}if !self.state.close.is_empty(){let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor close lacks its original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.state.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),1);let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=state.close.step_into(body,effect,scope.borrow()?)?;drop(done);return Ok(scope.forwarded())}if self.state.output.is_some(){let state=&mut *self.state;let turn=state.close.begin_granted(&mut state.output,effect);return Ok(reply.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)))} let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor binding close lacks its original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.state.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),2);let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=RetainedCloneBinding::close_into(&mut state.source,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 fn recover_close_into<'reply>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let (identity,route)=self.state.close_route.ok_or_else(||ValueError::invariant("cursor has no original close invocation"))?;let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor close recovery lacks its original invocation"))?;if invocation.identity()!=identity||invocation.mode()!=crate::OriginalEffectCallbackMode::Recover{return Err(ValueError::invariant("cursor close recovery changed invocation"))}let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,(identity,route))?;let child=scope.borrow()?;let done=match route{1=>state.close.recover_step_into(body,effect,child),2=>RetainedCloneBinding::recover_close_into(&mut state.source,body,effect,child),_=>Err(ValueError::invariant("cursor close route changed"))}?;drop(done);Ok(scope.forwarded())}
 fn close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if self.requires_original_birth(){return Err(ValueError::invariant("cursor Birth must settle before original close"))}if !self.requires_original_control(){return self.close_into(body,effect,reply)}let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor original close lacks invocation"))?;if !self.state.close.is_empty(){if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.state.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),3);let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=state.close.step_original_into(original,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}else{if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.state.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),4);let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=RetainedCloneBinding::close_original_into(&mut state.source,original,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}}
 fn recover_close_original_into<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let (identity,route)=self.state.close_route.ok_or_else(||ValueError::invariant("cursor has no original close invocation"))?;if !effect.invocation().is_some_and(|i|i.identity()==identity&&i.mode()==crate::OriginalEffectCallbackMode::Recover){return Err(ValueError::invariant("cursor original close recovery changed invocation"))}if route==1||route==2{return self.recover_close_into(body,effect,reply)}let state=&mut *self.state;let mut scope=reply.progress().scope(&mut state.close_route,(identity,route))?;let child=scope.borrow()?;let done=match route{3=>state.close.recover_step_original_into(original,body,effect,child),4=>RetainedCloneBinding::recover_close_original_into(&mut state.source,original,body,effect,child),_=>Err(ValueError::invariant("cursor close route changed"))}?;drop(done);Ok(scope.forwarded())}
 fn output_ready(&self)->bool{!self.state.closing&&!self.state.spent&&self.state.advance_action.is_none()&&self.state.output.is_some()}
 fn advance_demands(&self,source:RetainedCloneRef<'_,T>,_:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.state.closing||self.state.spent||self.state.advance_action.is_some()||self.state.output.is_some(){return Err(alias_invalid())}let binding=source.binding_demand(&self.state.source)?;let work=if binding.is_some(){source.binding_work_demand(&self.state.source)?}else{source.get().alias_work_demand()};if work>maximum_work_units{return Ok(Default::default())}Ok(binding.unwrap_or_else(||source.get().alias_demand()))}
 fn advance_work_demand(&self,source:RetainedCloneRef<'_,T>,_:usize,maximum_work_units:u64)->Result<u64,ValueError>{if self.state.closing||self.state.spent||self.state.advance_action.is_some()||self.state.output.is_some(){return Err(alias_invalid())}let work=if source.binding_demand(&self.state.source)?.is_some(){source.binding_work_demand(&self.state.source)?}else{source.get().alias_work_demand()};Ok(if work<=maximum_work_units{work}else{0})}
 fn advance_into<'reply>(&mut self,source:RetainedCloneRef<'_,T>,body:usize,maximum:u64,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let maximum=maximum.min(effect.remaining_work_units()?);let demand=self.advance_demands(source,body,maximum)?;let work=if source.binding_demand(&self.state.source)?.is_some(){source.binding_work_demand(&self.state.source)?}else{source.get().alias_work_demand()};if work>maximum||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if source.binding_demand(&self.state.source)?.is_some(){let turn=source.bind(&mut self.state.source,effect);return Ok(reply.complete(turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())).map_err(Into::into)))}let invocation=effect.invocation().ok_or_else(||ValueError::invariant("alias admission lacks original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive||self.state.advance_action.is_some(){return Err(ValueError::invariant("alias admission has unresolved original invocation"))}let identity=invocation.identity();let state=&mut *self.state;let mut scope=reply.scope(&mut state.advance_action,identity)?;let done=source.get().admit_alias_into(&mut state.output,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 fn recover_advance_into<'reply>(&mut self,source:RetainedCloneRef<'_,T>,_body:usize,_maximum:u64,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{let identity=self.state.advance_action.ok_or_else(||ValueError::invariant("alias admission has no original invocation"))?;if !effect.invocation().is_some_and(|i|i.identity()==identity&&i.mode()==crate::OriginalEffectCallbackMode::Recover){return Err(ValueError::invariant("alias admission recovery changed invocation"))}if source.binding_demand(&self.state.source)?.is_some(){return Err(ValueError::invariant("alias admission lost original source binding"))}let state=&mut *self.state;let mut scope=reply.scope(&mut state.advance_action,identity)?;let done=source.get().recover_alias_into(&mut state.output,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 fn take_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(self.output_ready()))}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{crate::retained_clone::retained_clone_cursor_take_demand::<T,bool>()}
    fn take<'reply>(&mut self,output:&mut Option<T>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>{crate::retained_clone::take_retained_clone_cursor_output!(self.output_ready(),self.state.output,output,self.state.spent,true,effect,reply,T,bool)}
 fn begin_close_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(!self.state.closing))}
 fn begin_close_demand(&self)->Result<crate::RetirementDemand,crate::ValueError>{let flags=usize::from(!self.state.closing);Ok(crate::RetirementDemand{copy_bytes:flags*std::mem::size_of::<bool>(),depth:usize::from(flags!=0),..Default::default()})}
fn begin_close_paid(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<crate::RetainedCloneProgress,crate::ValueError>{crate::retained_clone::start_retained_close(&mut self.state.closing,effect)}
 
 fn begin_close_into<'reply>(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if self.state.advance_action.is_some(){return Err(ValueError::invariant("alias admission remains unresolved"))}let turn=self.begin_close_paid(effect);Ok(reply.complete(turn.result.map(RetainedCloneStep::Progress).map_err(Into::into)))}
 fn close_started(&self)->bool{self.state.closing}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.state.closing{return Ok(0)}self.state.close.next_owner_work::<T>(self.state.output.is_some(),&self.state.source,body)}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.state.closing{return Err(alias_invalid())}self.state.close.next_owner_demands::<T>(self.state.output.is_some(),&self.state.source,body)}
 fn terminal_is_empty(&self)->bool{self.state.advance_action.is_none()&&self.state.close_route.is_none()&&self.state.output.is_none()&&self.state.source.is_none()&&self.state.close.is_empty()}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{self.state.close.next_copy_with_binding(&self.state.source)}
 fn next_close_capacity_byte_demand(&self,body:usize)->Result<usize,ValueError>{self.state.close.next_owner_capacity_with_binding::<T>(self.state.output.is_some(),body,&self.state.source)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{self.state.close.next_release_with_binding(&self.state.source)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{self.state.close.next_owner_depth_with_binding(self.state.output.is_some(),&self.state.source)}
}
impl<T:RetainedAlias> Drop for RetainedAliasCursor<T>{fn drop(&mut self){if self.state.output.is_none()&&self.state.source.is_none()&&self.state.close.is_empty(){unsafe{ManuallyDrop::drop(&mut self.state)}}else{assert!(std::thread::panicking(),"original immutable alias requires funded closure")}}}
